INSERT INTO news (title, slug, content, image, created_at) VALUES
('Поступление новых спорткаров в автосалон «Форза»', 'postuplenie-sportkarov', 'В наш автосалон поступила партия заряженных автомобилей из Европы и ОАЭ. Доступны эксклюзивные комплектации BMW и Audi с минимальным пробегом.', NULL, NOW()),
('Специальные условия по автокредитованию до конца месяца', 'lgotnyy-kredit', 'Совместно с ведущими банками-партнерами мы запустили сниженную процентную ставку на покупку автомобилей с пробегом. Оставьте заявку на сайте, чтобы узнать подробности.', NULL, NOW()),
('Итоги прошедшего тест-драйва внедорожников', 'itogi-test-drayva', 'Спасибо всем участникам нашего внедорожного уикенда! Тест-драйв Porsche Cayenne и других моделей показал отличные результаты на сложных участках трассы.', NULL, NOW());